	 ('AYj9mcRIbTTHvJfO7DZv','Pin versions in pip.','DL3013','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892936,1687881892936,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
