	 ('AYj9mcRJbTTHvJfO7DZ1','Avoid additional packages by specifying `--no-install-recommends`.','DL3015','iac',NULL,'external_hadolint','MAIN',1,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DZ4','Pin versions in `npm`.','DL3016','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DZ7','Pin versions in `apk add`. Instead of `apk add <package>` use `apk add <package>=<version>`.','DL3018','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DZ-','Use the `--no-cache` switch to avoid the need to use `--update` and remove `/var/cache/apk/*` when done installing packages.','DL3019','iac',NULL,'external_hadolint','MAIN',1,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DaB','You need a space or linefeed between the function name and body.','SC1095','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DaE','Unexpected `==`. For assignment, use `=`. For comparison, use `[ .. ]` or `[[ .. ]]`.','SC1097','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DaH','You need a space before the `#`.','SC1099','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRJbTTHvJfO7DaK','Please refrain from using inline ignore pragmas `# hadolint ignore=DLxxxx`','DL1001','iac',NULL,'external_hadolint','MAIN',0,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892937,1687881892937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRKbTTHvJfO7DaN','Use semicolon or linefeed before `done` (or quote to make it literal).','SC1010','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRKbTTHvJfO7DaQ','Quote/escape special characters when using `eval`, e.g. `eval "a=(b)"`.','SC1098','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
