	 ('AYj9mcRKbTTHvJfO7DaT','Use `COPY` instead of `ADD` for files and folders.','DL3020','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRKbTTHvJfO7DaW','`COPY` with more than 2 arguments requires the last argument to end with `/`','DL3021','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRKbTTHvJfO7DaZ','`COPY --from` should reference a previously defined `FROM` alias','DL3022','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRKbTTHvJfO7Dac','`COPY --from` cannot reference its own `FROM` alias','DL3023','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892938,1687881892938,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Daf','`FROM` aliases (stage names) must be unique','DL3024','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Dai','Use arguments JSON notation for CMD and ENTRYPOINT arguments','DL3025','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Dal','Use only an allowed registry in the `FROM image`','DL3026','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Dao','Do not use `apt` as it is meant to be an end-user tool, use `apt-get` or `apt-cache` instead','DL3027','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Dar','Pin versions in gem install. Instead of `gem install <gem>` use `gem install <gem>:<version>`','DL3028','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRLbTTHvJfO7Dau','Do not use --platform flag with FROM.','DL3029','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
