	 ('AYj9mcRLbTTHvJfO7Dax','This is a unicode non-breaking space. Delete it and retype as space.','SC1018','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892939,1687881892939,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7Da0','Scripts are case sensitive. Use `if`, not `If`.','SC1081','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7Da3','This `{/}` is literal. Check expression (missing `;/\n`?) or quote it.','SC1083','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7Da6','Don''t use `$` on the iterator name in for loops.','SC1086','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7Da9','`$` is not used specially and should therefore be escaped.','SC1000','iac',NULL,'external_hadolint','MAIN',1,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7DbA','Braces are required when expanding arrays, as in `${array[idx]}`.','SC1087','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7DbD','This `\c` will be a regular `''c''` in this context.','SC1001','iac',NULL,'external_hadolint','MAIN',0,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcRMbTTHvJfO7DbG','Remove space after `=` if trying to assign a value (or for empty string, use `var='''' ...`).','SC1007','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892940,1687881892940,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR3bTTHvJfO7DbJ','Use <code>cd ... &#124;&#124; exit</code> in case `cd` fails.','SC2164','iac',NULL,'external_hadolint','MAIN',0,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892983,1687881892983,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR4bTTHvJfO7DbM','For command expansion, the tick should slant left (` vs ´).','SC1077','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
