	 ('AYj9mcR4bTTHvJfO7DbP','Use absolute WORKDIR.','DL3000','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR4bTTHvJfO7DbS','For some bash commands it makes no sense running them in a Docker container like ssh, vim, shutdown, service, ps, free, top, kill, mount, ifconfig.','DL3001','iac',NULL,'external_hadolint','MAIN',1,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR4bTTHvJfO7DbV','Last user should not be root.','DL3002','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR4bTTHvJfO7DbY','Use WORKDIR to switch to a directory.','DL3003','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYfENKyUsqx_1CCtPomX','Variables should not be self-assigned','S1656','sonarapex',NULL,'apex','ALL',2,'READY','apex','CONSTANT_ISSUE',NULL,'3min',NULL,NULL,false,'HTML',2,NULL,false,false,1682623999124,1687881893115,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR4bTTHvJfO7Dbb','This is actually an end quote, but due to next char, it looks suspect.','SC1079','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892984,1687881892984,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR5bTTHvJfO7Dbe','Do not use sudo as it leads to unpredictable behavior. Use a tool like gosu to enforce root.','DL3004','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892985,1687881892985,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
	 ('AYj9mcR5bTTHvJfO7Dbh','Did you forget to close this double-quoted string?','SC1078','iac',NULL,'external_hadolint','MAIN',2,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',1,NULL,false,true,1687881892985,1687881892985,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
