	 ('AYj9mcR5bTTHvJfO7Dbn','Do not use apt-get dist-upgrade.','DL3005','iac',NULL,'external_hadolint','MAIN',3,'READY','docker','CONSTANT_ISSUE',NULL,'5min',NULL,NULL,false,'HTML',2,NULL,false,true,1687881892985,1687881892985,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
